enum Expr {
    Lit(i64),
    Binary { left: Box<Expr>, op: char, right: Box<Expr> },   // named child fields
}

fn print(e: &Expr) -> String {
    match e {
        Expr::Lit(v) => v.to_string(),
        Expr::Binary { left, right, .. } => format!("({}{})", print(left), print(right)),
    }
}
